#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
# ⚠ DO NOT REMOVE — Scope: builds erp/ad_search_definitions.js = legacy's AD_SearchDefinition (its DDL and its rows) for the boot overlay erp/ad_search_overlay.js
#   (bim-compiler prompts/CLI_ERP_IVR.md §41 H1). EXTRACT ONLY from the pilot (idempiere_pilot = the oracle, docker container `postgres`), client 0/11. The seed carries no
#   AD_SearchDefinition table; legacy's document search (AbstractDocumentSearch.openDocumentsByDocumentNo) reads it. READ the printed §SEARCHDEF line after a run.
import json, os, subprocess

HERE = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(os.path.dirname(HERE), 'ad_search_definitions.js')
def pg(sql):
    r = subprocess.run(['docker', 'exec', '-i', 'postgres', 'psql', '-U', 'postgres', '-d', os.environ.get('PG_DB', 'idempiere_pilot'), '-tA', '-c', 'set search_path=adempiere;' + sql], capture_output=True, text=True, check=True)
    return [l for l in r.stdout.split('\n') if l and l != 'SET']
T = 'ad_searchdefinition'
cols = [l.split('|') for l in pg("select column_name || '|' || case when data_type in ('numeric','integer','bigint') then 'NUMERIC' else 'TEXT' end from information_schema.columns where table_schema='adempiere' and table_name='%s' order by ordinal_position" % T)]
pk = pg("select kcu.column_name from information_schema.table_constraints tc join information_schema.key_column_usage kcu using (constraint_name, table_schema) where tc.table_schema='adempiere' and tc.table_name='%s' and tc.constraint_type='PRIMARY KEY' order by kcu.ordinal_position" % T)
sel = ', '.join('%s::text as %s' % (c, c) for c, _ in cols)
rows = [json.loads(l) for l in pg('select row_to_json(x)::text from (select %s from %s where ad_client_id in (0,11) order by %s) x' % (sel, T, T + '_id'))]
data = {'table': T, 'columns': cols, 'pk': pk, 'rows': rows, 'source': 'idempiere_pilot adempiere.' + T + ' (client 0/11)'}
with open(OUT, 'w') as f:
    f.write('// GENERATED by erp/patches/build_search_definitions.py from the pilot - do not edit (bim-compiler prompts/CLI_ERP_IVR.md §41 H1)\n')
    f.write("(function (g) { g.AD_SEARCH_DEFINITIONS = " + json.dumps(data, ensure_ascii=False) + "; if (typeof module !== 'undefined' && module.exports) module.exports = g.AD_SEARCH_DEFINITIONS; })(typeof window !== 'undefined' ? window : globalThis);\n")
print('§SEARCHDEF columns=%d pk=%s rows=%d (%s) -> %s' % (len(cols), pk, len(rows), ', '.join('%s/%s' % (r['name'], r['transactioncode']) for r in rows), OUT))
